mapper.select:
select
comment.*,
users.nick_name,
users.head_img,
knowledge.title,
knowledge.banner_img
from comment comment
left join users users on comment.user_id = users.id
left join knowledge knowledge on comment.knowledge_id = knowledge.id

    and comment.id = #{id}
    and comment.content = #{content}
    and comment.user_id = #{userId}
    and comment.knowledge_id = #{knowledgeId}
    and comment.to_user_id = #{toUserId}
    and comment.parent_id = #{parentId}
    and users.nick_name like concat('%',#{nickName},'%')
    and users.head_img = #{headImg}
    and knowledge.title like concat('%',#{title},'%')


    limit #{current},#{pageSize}

select count(*) from comment comment
left join users users on comment.user_id = users.id
left join knowledge knowledge on comment.knowledge_id = knowledge.id

    and comment.id = #{id}
    and comment.content = #{content}
    and comment.user_id = #{userId}
    and comment.knowledge_id = #{knowledgeId}
    and comment.to_user_id = #{toUserId}
    and comment.parent_id = #{parentId}
    and users.nick_name like concat('%',#{nickName},'%')
    and users.head_img = #{headImg}
    and knowledge.title like concat('%',#{title},'%')
